<template>
  <div class="container-form d-flex flex-column">
    <webview :src="surveyURL" v-if="isInternet" class="flex-grow-1" />
    <div v-else class="flex-grow-1 align-center">
      <HelpWatermark :config="noConnection" class="align-center" />
    </div>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'

import SURVEY_API_EVENTS from '@/config/events/serversAPI/surveyEvents'
import surveyTypes from '@/config/surveyTypes'

import rendererEventsService from '@/services/renderer/rendererEvents'

import HelpWatermark from '@/components/shared/HelpWatermark'

export default {
  name: 'ReferAndWinView',
  components: { HelpWatermark },
  data() {
    return {
      surveyURL: '',
      isInternet: false,
      noConnection: {
        icon: 'mdi-cloud-off-outline',
        messages: ['notification.helpCenter.internetConnectionError'],
      },
    }
  },
  computed: {
    ...mapGetters('account', ['getCountry', 'getPos']),
  },
  methods: {
    getSurveyURL(event, payload) {
      const surveyReplies = SURVEY_API_EVENTS.events.getSurveyURL.replies
      const replies = {
        [`${surveyReplies.success}`]: () => {
          this.isInternet = true
          this.surveyURL = payload.data
        },
        [`${surveyReplies.error}`]: () => {
          this.isInternet = false
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  mounted() {
    rendererEventsService.subscribe(
      SURVEY_API_EVENTS.replyChannel,
      this.getSurveyURL
    )
    rendererEventsService.send(SURVEY_API_EVENTS.channel, {
      event: SURVEY_API_EVENTS.events.getSurveyURL.name,
      data: {
        pos: this.getPos,
        country: this.getCountry.phoneCode,
        surveyType: surveyTypes.referAndWin,
      },
    })
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(SURVEY_API_EVENTS.replyChannel)
  },
}
</script>

<style lang="scss" scoped>
.container-form {
  height: 101vh;
}
</style>
